// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;

    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(uint256 depositAmount) public {
        depositAmount = bound(depositAmount, 0, 1 ether);

        vm.deal(address(this), depositAmount);

        if (depositAmount > 0) {
            (bool sent, ) = address(c).call{value: depositAmount}("");
            require(sent);
        }

        bool ok;
        try c.withdrawAll(address(0x123)) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(address(c).balance == 0);
    }
}
